"""Depth calculation and validation."""

from query_ast import ParsedQuery, Selection


def selection_depth(selection: Selection, fragments: dict[str, list[Selection]], seen: frozenset[str] = frozenset()) -> int:
    if selection.fragment:
        return 1
    if not selection.children:
        return 1
    return 1 + max(selection_depth(child, fragments, seen) for child in selection.children)


def query_depth(parsed: ParsedQuery) -> int:
    if not parsed.selections:
        return 0
    return max(selection_depth(selection, parsed.fragments) for selection in parsed.selections)


def validate_depth(parsed: ParsedQuery, max_depth: int) -> dict:
    depth = query_depth(parsed)
    if depth > max_depth:
        return {"ok": False, "error": "query_too_deep", "depth": depth, "max_depth": max_depth}
    return {"ok": True, "depth": depth, "max_depth": max_depth}

