from depth_validator import query_depth, validate_depth
from parser import parse_query


def test_shallow_query_depth():
    assert query_depth(parse_query("{ viewer { id } }")) == 2


def test_nested_query_depth():
    assert query_depth(parse_query("{ viewer { account { invoices { id } } } }")) == 4


def test_query_over_limit_is_rejected():
    assert validate_depth(parse_query("{ a { b { c } } }"), 2)["error"] == "query_too_deep"


def test_query_at_limit_is_allowed():
    assert validate_depth(parse_query("{ a { b } }"), 2)["ok"] is True


def test_named_fragment_depth_is_counted():
    parsed = parse_query("query { viewer { ...DeepFields } } fragment DeepFields on User { account { invoices { id } } }")
    assert query_depth(parsed) == 5


def test_named_fragment_over_limit_is_rejected():
    parsed = parse_query("query { viewer { ...DeepFields } } fragment DeepFields on User { account { invoices { id } } }")
    assert validate_depth(parsed, 3)["ok"] is False


def test_inline_fragment_depth_is_counted():
    parsed = parse_query("{ node { ... on User { account { id } } } }")
    assert query_depth(parsed) == 4


def test_fragment_within_limit_is_allowed():
    parsed = parse_query("query { viewer { ...NameFields } } fragment NameFields on User { name }")
    assert validate_depth(parsed, 3)["ok"] is True


def test_response_keys_for_rejection_are_stable():
    parsed = parse_query("{ a { b { c } } }")
    assert set(validate_depth(parsed, 2)) == {"ok", "error", "depth", "max_depth"}


def test_response_keys_for_success_are_stable():
    assert set(validate_depth(parse_query("{ a }"), 2)) == {"ok", "depth", "max_depth"}


def test_multiple_top_level_uses_deepest_branch():
    assert query_depth(parse_query("{ a b { c { d } } }")) == 3


def test_empty_query_depth_zero():
    assert query_depth(parse_query("")) == 0


def test_common_wrong_fix_does_not_ignore_named_fragments():
    parsed = parse_query("query { viewer { ...Deep } } fragment Deep on User { a { b { c { d } } } }")
    assert validate_depth(parsed, 3)["ok"] is False


def test_common_wrong_fix_does_not_reject_all_fragments():
    parsed = parse_query("query { viewer { ...Name } } fragment Name on User { name }")
    assert validate_depth(parsed, 3)["ok"] is True


def test_fragment_spread_without_children_still_counts_field():
    parsed = parse_query("query { viewer { ...Name } } fragment Name on User { name }")
    assert query_depth(parsed) == 3


def test_inline_fragment_type_condition_does_not_add_extra_field_level():
    assert query_depth(parse_query("{ node { ... on User { id } } }")) == 3


def test_deep_inline_fragment_rejected():
    assert validate_depth(parse_query("{ node { ... on User { a { b { c } } } } }"), 4)["ok"] is False


def test_sibling_fragment_depth_uses_maximum():
    parsed = parse_query("query { viewer { ...A ...B } } fragment A on User { name } fragment B on User { account { id } }")
    assert query_depth(parsed) == 4


def test_limit_one_allows_single_field():
    assert validate_depth(parse_query("{ id }"), 1)["ok"] is True


def test_limit_one_rejects_child_field():
    assert validate_depth(parse_query("{ viewer { id } }"), 1)["ok"] is False
